"    if (fullPhone) {
      const pointsEarned = Math.floor(total / 100);
      setCustomerDb(prev => {
        const existing = prev[fullPhone] || { name: customerName, phone: fullPhone, points: 0, orders: 0, totalSpent: 0, balance: 0 };
        const balanceChange = isCreditCheckout ? -grandTotal : 0;
        return {
          ...prev,
          [fullPhone]: {
            ...existing,
            name: customerName || existing.name,
            points: existing.points + pointsEarned,
            orders: existing.orders + 1,
            totalSpent: existing.totalSpent + total,
            balance: (existing.balance || 0) + balanceChange
          }
        };
      });
    }"

